
// .............1
//constant repulsion/sttraction
export const fieldAttraction = (fieldPoint: Vector3, attractor: Vector3, strength: number) => {
	const dv= Vector3.sub(fieldPoint, attractor);
	const v =new Vector3(dv.x, dv.y, 0.0);
	v.normalize();
	v.mult(strength);
	return v;
}

// .............. 2
//constant rotation
export const fieldRotation = (fieldPoint: Vector3, attractor: Vector3, strength: number) => {    
	const dr = fieldAttraction(fieldPoint, attractor, strength);
	const v = new Vector3(-dr.y, dr.x, 0.0);
	return v;
}

// .............. 3
//fading factor exponential
export const fieldComposite = (fieldPoint : Vector3, attractor: Vector3, strengthAttraction: number, strengthRotation: number) => {
	const ddf=fieldRotation(fieldPoint, attractor, strengthRotation);
	ddf.add(fieldAttraction(fieldPoint, attractor, strengthAttraction));
	ddf.mult(fadeExp(fieldPoint, attractor, 0.00005));
	return ddf;
}
//fading factor exponential
const fadeExp = (fieldPoint: Vector3, attractor: Vector3, fade: number) => {
  	const dv=Vector3.sub(fieldPoint, attractor);
	//   return Math.exp(-fade*dv.magSq());
	return gaussianFalloff(fade, dv)
}
 
const magSq = (dv: Vector3) => {
  	return dv.x*dv.x + dv.y*dv.y + dv.z*dv.z; // 3D
}
const gaussianFalloff = (fade, dv) =>{
  return Math.exp(-fade * magSq(dv));
}

// .............. 4
export const fieldAttractors = (vs, value, fieldPoint: Vector3) => {
  const df=new Vector3();      
  for(let k=0; k< vs.length; ++k) {
    df.add(fieldComposite(fieldPoint, vs[k], value[k]*0.2, value[k]));
  }
  return df;
}


// .............. 7
export const allAttractors = (vs, value, fieldPoint: Vector3) => {
	const df=new Vector3();

	for(let k=0; k< vs.length; ++k) {
		df.add(composite(fieldPoint, vs[k], value[k]*0.2, value[k]));
	}
	
	return df;
}
const composite = (fieldPoint: Vector3, attractor: Vector3, strengthAttraction: number, strengthRotation: number) => {
	const ddf=fieldRotation(fieldPoint, attractor, strengthRotation);
	ddf.add(fieldAttraction(fieldPoint, attractor, strengthAttraction));
	ddf.mult(fadeExp(fieldPoint, attractor, 0.00005));
	
	return ddf;
}


export class Vector3 {
	static add(v0: Vector3, v1: Vector3): Vector3 {
		return new Vector3(v0.x + v1.x, v0.y + v1.y, v0.z + v1.z);
	}
	static sub(v0: Vector3, v1: Vector3): Vector3 {
		return new Vector3(v0.x - v1.x, v0.y - v1.y, v0.z - v1.z);
	}
	public x = 0
	public y = 0
	public z = 0
	constructor(x: number = 0, y: number = 0, z: number = 0) {
		this.x = x ;
		this.y = y ;
		this.z = z ;
	}
	public normalize(): Vector3 {
		let len: number = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
		this.x = this.x / len;
		this.y = this.y / len;
		this.z = this.z / len;
		return new Vector3(this.x, this.y, this.z);
	}
	public mult(v: number): Vector3 {
		this.x *= v;
		this.y *= v;
		this.z *= v;
		return new Vector3(this.x, this.y, this.z);
	}
	public add(v: Vector3): Vector3 {
		this.x += v.x;
		this.y += v.y;
		this.z += v.z;
		return new Vector3(this.x, this.y, this.z);
	}
	public set(v: Vector3): Vector3 {
		this.x = v.x;
		this.y = v.y;
		this.z = v.z;
		return new Vector3(this.x, this.y, this.z);
	}
}